head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > displayFormatter]<br/>컴포넌트에 포커스가 해제된 상태일때 표시될 입력값의 포맷을 변환하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "사용자 정의 함수의 이름을 displayFormatter 속성으로 설정합니다.",
        "사용자 정의 함수의 파라미터(val) 로 컴포넌트에 입력된 실제값이 전달됩니다.",
        "사용자 정의 함수의 반환값이 컴포넌트에 표시되는 입력값으로 적용됩니다.",
        "displayFormatter 의 반환값으로 표시되는 값과 실제 입력값(getValue 반환값)이 다릅니다.",
        "displayFormatter 속성을 설정하면 displayFormat 속성은 무시됩니다.",
        "setDisplayFormatter 메소드로 displayFormatter 속성값을 동적으로 변경할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 표시값(input element 의 value)
scwin.get_text_display = function(target) {
    let rtn = '';
    let inputElem = (target.render && target.render.tagName === "INPUT") ? target.render : (target.render ? target.render.querySelector("input") : null);

    if (inputElem) {
        rtn = inputElem.value;
        wf_body_bottom.getObj("scwin").setReturnValue("text(display) : " + rtn);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("input element not found");
    }
}

// 실제 입력값
scwin.get_value = function(target) {
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + target.getValue());
}

// 사용자 정의 displayFormatter 함수 정의
scwin.fn_dear = function(val) {
    return "Dear " + val;
};

scwin.fn_won = function(val) {
    if (val === "" || val === null || val === undefined || isNaN(Number(val))) return val;
    return "₩" + Number(val).toLocaleString() + "원";
};

scwin.fn_brackets = function(val) {
    return "[" + val + "]";
};



// target1 : displayFormatter=scwin.fn_dear (displayFormat 미설정)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("John");
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text_display(target1);
}

scwin.btn_getValue1_onclick = function (e) {
    scwin.get_value(target1);
}

// target2 : displayFormatter=scwin.fn_dear + displayFormat=#:##-## (displayFormat 무시 검증)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("John");
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text_display(target2);
}

scwin.btn_getValue2_onclick = function (e) {
    scwin.get_value(target2);
}

// target3 : dataType=number + displayFormatter=scwin.fn_won (displayFormat 으로 지원 안되는 포맷)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("-1234.56");
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text_display(target3);
}

scwin.btn_getValue3_onclick = function (e) {
    scwin.get_value(target3);
}

// target4 : displayFormatter=scwin.fn_dear -> setDisplayFormatter("scwin.fn_brackets") 동적 변경
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("John");
};

scwin.btn_getText4_onclick = function (e) {
    scwin.get_text_display(target4);
}

scwin.btn_getValue4_onclick = function (e) {
    scwin.get_value(target4);
}

scwin.btn_setDisplayFormatter4_onclick = function (e) {
    target4.setDisplayFormatter("scwin.fn_brackets");
    target4.setValue(target4.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("setDisplayFormatter('scwin.fn_brackets') 호출 완료");
};



// 전체 일괄 실행
scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i < 5; i ++) {
        eval("scwin.btn_setValue"+i+"_onclick()");
    }
}

scwin.btn_getAllText_onclick = function (e) {
    for (var i = 1; i < 5; i ++) {
        eval("scwin.btn_getText"+i+"_onclick()");
    }
};

scwin.btn_getAllValue_onclick = function (e) {
    for (var i = 1; i < 5; i ++) {
        eval("scwin.btn_getValue"+i+"_onclick()");
    }
};
